var score: int = 0
var high_score: int = 0
var current_topic_title: String = ""
var topic_records: Dictionary = {}
var questions: Array[Question] = []
var last_wrong_questions: Array[Question] = []


func _ready() -> void:
	apply_saved_audio_settings()
	load_topic_records()
	if questions.is_empty():
		var q_opts1: Array[String] = ["A", "B"]
		var q_opts2: Array[String] = ["C", "D"]
		questions = [
			Question.new("Domanda 1", q_opts1, 0),
			Question.new("Domanda 2", q_opts2, 1)
		]


func apply_saved_audio_settings() -> void:
	if not FileAccess.file_exists("user://settings.json"):
		return

	var file: FileAccess = FileAccess.open("user://settings.json", FileAccess.READ)
	if file == null:
		return

	var content: String = file.get_as_text()
	file.close()

	var json: JSON = JSON.new()
	if json.parse(content) != OK:
		return

	if not (json.data is Dictionary):
		return

	var data: Dictionary = json.data
	var master_idx: int = AudioServer.get_bus_index("Master")
	var music_idx: int = AudioServer.get_bus_index("Music")
	var sfx_idx: int = AudioServer.get_bus_index("SFX")

	if master_idx >= 0 and data.has("master_volume"):
		var master_vol: float = maxf(0.0001, float(data["master_volume"]))
		AudioServer.set_bus_volume_db(master_idx, linear_to_db(master_vol))

	if music_idx >= 0 and data.has("music_volume"):
		var music_vol: float = maxf(0.0001, float(data["music_volume"]))
		AudioServer.set_bus_volume_db(music_idx, linear_to_db(music_vol))

	if sfx_idx >= 0 and data.has("sfx_volume"):
		var sfx_vol: float = maxf(0.0001, float(data["sfx_volume"]))
		AudioServer.set_bus_volume_db(sfx_idx, linear_to_db(sfx_vol))

	if master_idx >= 0 and data.has("is_muted"):
		AudioServer.set_bus_mute(master_idx, bool(data["is_muted"]))


func save_high_score() -> void:
	pass


func save_topic_records() -> void:
	var json_string: String = JSON.stringify(topic_records)
	var file: FileAccess = FileAccess.open("user://records.json", FileAccess.WRITE)
	if file != null:
		file.store_string(json_string)


func load_topic_records() -> bool:
	if not FileAccess.file_exists("user://records.json"):
		topic_records = {}
		return false

	var file: FileAccess = FileAccess.open("user://records.json", FileAccess.READ)
	if file == null:
		topic_records = {}
		return false

	var content: String = file.get_as_text()
	var json: JSON = JSON.new()
	var parse_result: Error = json.parse(content)

	if parse_result != OK:
		topic_records = {}
		return false

	if json.data is Dictionary:
		topic_records = json.data
		return true

	topic_records = {}
	return false


func get_topic_record(topic_name: String) -> int:
	if topic_records.has(topic_name):
		return int(topic_records[topic_name])
	return 0


func get_sorted_records(source: Dictionary = {}) -> Array[Dictionary]:
	var target: Dictionary = source if not source.is_empty() else topic_records
	var records_list: Array[Dictionary] = []
	for topic in target:
		records_list.append({
			"topic": str(topic),
			"score": int(target[topic])
		})
	records_list.sort_custom(func(a: Dictionary, b: Dictionary) -> bool:
		return a["score"] > b["score"]
	)
	return records_list


func filter_difficult_questions(source: Array[Question]) -> Array[Question]:
	var filtered: Array = source.filter(func(q: Question) -> bool:
		return q != null and q.options.size() > 2
	)
	var result: Array[Question] = []
	result.assign(filtered)
	return result


func filter_wrong_questions(source: Array[Question], wrong_pool: Array[Question]) -> Array[Question]:
	var filtered: Array = source.filter(func(q: Question) -> bool:
		return q != null and wrong_pool.has(q)
	)
	var result: Array[Question] = []
	result.assign(filtered)
	return result

